#[test]
fn existing_aggregate_io_admits_exact_raw_frontier_and_freezes_typed_owner() {
    use protocol::{Mutation, OpText};
    use semio_framework_value::{DslValue as V, ToValue};
    use crate::standards::v1_7::subsets::base::schema::{conformance_support as support, snapshot::{PdfSnapshot, PdfPage, PdfObject, PdfDecimal, PdfDictEntry}};
    use super::super::apply_vt_conformance_mutation;
    fn frame(value: &V) -> Vec<u8> {
        let payload = semio_framework_pack_json::to_string(&semio_framework_pack_json::from_dsl_value(value)).into_bytes();
        let mut writer = dsl::ByteWriter::new(); writer.write_u8(1); writer.write_u8(18); writer.write_varint_u64(payload.len() as u64); writer.write_bytes(&payload); writer.into_bytes()
    }
    fn spelling(value: &V) -> String { let payload = semio_framework_pack_json::to_string(&semio_framework_pack_json::from_dsl_value(value)); format!("pdf-vt-mutation payload={}", payload.bytes().map(|byte| format!("{byte:02x}")).collect::<String>()) }
    let corpus = semio_framework_pack_json::parse(include_str!("../../../../../🧫️fixtures/🪢️raw-graph-operation/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();
    for schema in [PdfSnapshot::default().schema, "neutral-custom-frozen-owner".into()] {
    for word in corpus.get("neutralWords").and_then(semio_framework_pack_json::Value::as_array).unwrap() {
        let word = u64::from_str_radix(word.as_str().unwrap(), 16).unwrap();
        let mut base = PdfSnapshot::default(); base.schema = schema.clone();
        let catalog = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Catalog".into()))]));
        let pages = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Pages".into())), ("Count", PdfObject::Int(1)), ("MediaBox", PdfObject::numbers(&[0.0, 0.0, 100.0, 100.0]))]));
        let page = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Page".into())), ("Parent", PdfObject::Ref(pages))]));
        support::set_entry(&mut base, catalog, "Pages", PdfObject::Ref(pages)); support::set_entry(&mut base, pages, "Kids", PdfObject::Array(vec![PdfObject::Ref(page)]));
        base.trailer.push(PdfDictEntry::new("Root", PdfObject::Ref(catalog))); base.pages.push(PdfPage::new(100.0, 100.0)); base.pages[0].duration = Some(f64::from_bits(word));
        let extra = support::insert_object(&mut base, PdfObject::Dict(vec![PdfDictEntry::new("Repeated", PdfObject::Real(PdfDecimal { negative:true, coefficient:"0".into(), scale:0 })), PdfDictEntry::new("Repeated", PdfObject::Str(vec![0,255,13,10])), PdfDictEntry::new("Min", PdfObject::Int(i64::MIN)), PdfDictEntry::new("Max", PdfObject::Int(i64::MAX))]));
        let duplicate = base.objects.iter().find(|object| object.id == extra).unwrap().clone(); base.objects.push(duplicate);
        let original = store::pack_rt::encode_wire_value(&base.to_value());
        let mut expected = base.clone(); support::insert_object(&mut expected, PdfObject::Str(b"new ordered retained octets".to_vec())); expected.catalog_extra.push(PdfDictEntry::new("Unrelated", PdfObject::Name("retained".into())));
        let payload = V::Object(vec![("mutation".into(), V::String("restoreDpartGraph".into())), ("graph".into(), V::Object(vec![("objects".into(), expected.objects.to_value()), ("catalogExtra".into(), expected.catalog_extra.to_value())]))]);
        let bytes = frame(&payload);
        let decoded = PdfVtMutation::decode_op(&bytes); assert!(decoded.is_ok(), "existing decode_op must admit the new typed operation, not refuse its tag"); let decoded = decoded.unwrap();
        assert_eq!(decoded.encode_op().unwrap(), bytes); assert_eq!(PdfVtMutation::parse_op(&spelling(&payload)).unwrap(), decoded);
        let undo = decoded.inverse(&base).unwrap(); let mut next = base.clone(); assert!(apply_vt_conformance_mutation(&mut next, &decoded).messages().is_empty());
        assert_eq!(next.schema, schema); assert_eq!(next.pages[0].duration.unwrap().to_bits(), word); assert_eq!(store::pack_rt::encode_wire_value(&next.to_value()), store::pack_rt::encode_wire_value(&expected.to_value()));
        for undo in undo { assert!(apply_vt_conformance_mutation(&mut next, &undo).messages().is_empty()); }
        assert_eq!(store::pack_rt::encode_wire_value(&next.to_value()), original);
        let raw = semio_framework_pack_json::to_string(&semio_framework_pack_json::from_dsl_value(&payload)).into_bytes(); let mut overlong = vec![1,18]; let mut remaining = raw.len() as u64; for _ in 0..9 { overlong.push((remaining as u8 & 127)|128); remaining >>= 7; } overlong.push(remaining as u8); overlong.extend(raw); assert_eq!(PdfVtMutation::decode_op(&overlong).unwrap(), decoded);
        let mut bad = payload.clone(); if let V::Object(fields) = &mut bad { fields.push(("schema".into(), V::String("must-not-replace-frozen-owner".into()))); } assert!(PdfVtMutation::decode_op(&frame(&bad)).is_err()); assert!(PdfVtMutation::parse_op(&spelling(&bad)).is_err());
    }
    }
    let malformed = semio_framework_pack_json::parse(r#"{"mutation":"restoreDpartGraph","graph":{"objects":[{"id":{"num":1,"gen":0},"value":{"kind":"bool","value":true,"unused":1}}],"catalogExtra":[]}}"#, semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();
    let malformed = semio_framework_pack_json::to_dsl_value(&malformed); assert!(PdfVtMutation::decode_op(&frame(&malformed)).is_err()); assert!(PdfVtMutation::parse_op(&spelling(&malformed)).is_err());
    eprintln!("[DEBUG] existing VT aggregate IO exercised exact raw frontier, two frozen identities, eight IEEE words and actual role/varint policies");
}
